-- 031_briefings.sql
-- Persisted briefing snapshots — one per (user, date, slot). Generated by
-- the scheduler ~3 minutes before slot_time so the card is warm on open.

CREATE TABLE IF NOT EXISTS public.briefings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    slot TEXT NOT NULL CHECK (slot IN ('morning','evening')),
    briefing_date DATE NOT NULL,
    sections JSONB NOT NULL DEFAULT '{}'::jsonb,
    generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    delivered_at TIMESTAMPTZ,
    channels_delivered TEXT[] DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (user_id, slot, briefing_date)
);

CREATE INDEX IF NOT EXISTS idx_briefings_user_recent
    ON public.briefings (user_id, briefing_date DESC);

ALTER TABLE public.briefings ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS briefings_owner_all ON public.briefings;
CREATE POLICY briefings_owner_all
    ON public.briefings
    FOR ALL
    USING (auth.uid() = user_id)
    WITH CHECK (auth.uid() = user_id);

NOTIFY pgrst, 'reload schema';
